// Generic recursion template
function solve(input) {
  // 1. Base case: smallest problem, solved directly
  if (baseCondition(input)) {
    return baseValue;
  }

  // 2. Recursive case: break down, trust the result
  const smallerResult = solve(smallerInput(input));

  // 3. Combine: build answer from smaller result
  return combine(input, smallerResult);
}

// --- Concrete example: factorial ---
function factorial(n) {
  if (n <= 1) return 1;           // base case
  return n * factorial(n - 1);   // recursive case
}

// --- With memoization wrapper ---
function memoize(fn) {
  const cache = new Map();
  return function(n) {
    if (cache.has(n)) return cache.get(n);
    const result = fn(n);         // fn still calls the memoized version
    cache.set(n, result);
    return result;
  };
}

// Memoized fibonacci
const fib = memoize(function(n) {
  if (n <= 1) return n;
  return fib(n - 1) + fib(n - 2); // fib here refers to memoized version
});
